import type { RequestHandler } from "msw"
import { crudFromFixtures } from "./crudFromFixtures"
import { fileHandlers } from "./files"
import { voiceHandlers } from "./voice" // module:llm
import { wsHandlers } from "./ws"

// screens/<id>/fixtures.json is generated by `make api-client` from backend/api/resources/<id>/seed.json.
const fixtures = import.meta.glob<Record<string, unknown>[]>("../screens/*/fixtures.json", { eager: true, import: "default" })
// Optional per-screen overrides: screens/<id>/mocks.ts exports `handlers: RequestHandler[]`.
const overrides = import.meta.glob<{ handlers: RequestHandler[] }>("../screens/*/mocks.ts", { eager: true })

const idOf = (path: string) => path.split("/")[2]

export const handlers: RequestHandler[] = [
  ...Object.values(overrides).flatMap((m) => m.handlers),
  ...Object.entries(fixtures).flatMap(([path, rows]) => crudFromFixtures(`/api/${idOf(path)}`, rows)),
  ...fileHandlers,
  ...voiceHandlers, // module:llm
  ...wsHandlers,
]
